INSERT INTO public.contratos (id, numero, pedido_id, status, clausulas, gerado_em, assinado_em, arquivo_assinado_path, arquivo_assinado_nome, arquivo_assinado_tamanho, created_at, updated_at) VALUES ('4d0a4943-e6fe-439b-9854-67e42092faa6', 96, '4220ebad-294a-42ab-9490-16e008117c16', 'assinado', '[{"texto": "Fabricação e instalação dos móveis planejados descritos no resumo deste contrato, conforme o orçamento aprovado pelo CONTRATANTE.", "titulo": "Objeto"}, {"texto": "As medidas são confirmadas por medição técnica no local antes do início da produção. Alterações de projeto após a confirmação podem alterar valor e prazo.", "titulo": "Medidas e projeto"}, {"texto": "O prazo de entrega é contado em dias úteis a partir da assinatura deste contrato e da confirmação das medidas, podendo ser prorrogado por motivo de força maior ou atraso na liberação do local.", "titulo": "Prazo de entrega"}, {"texto": "O pagamento será realizado conforme a forma e as condições indicadas neste contrato. Parcelas pagas em cheque são consideradas quitadas após a compensação.", "titulo": "Pagamento"}, {"texto": "A CONTRATADA oferece garantia de 5 (cinco) anos contra defeitos de fabricação, excluídos danos por mau uso, umidade excessiva ou intervenção de terceiros.", "titulo": "Garantia"}, {"texto": "Não estão inclusos eletrodomésticos, cubas, metais, pedras não especificadas e serviços de alvenaria, elétrica ou hidráulica.", "titulo": "Itens não inclusos"}, {"texto": "Em caso de rescisão após o início da produção, os valores correspondentes aos materiais adquiridos e aos serviços executados não serão restituídos.", "titulo": "Rescisão"}]', '2026-07-30 10:00:00-03', '2026-08-01 15:00:00-03', NULL, NULL, NULL, '2026-10-30 09:47:35.891551-03', '2026-10-30 09:47:35.891551-03');
